const raw = $input.first().json;
const body = raw.body || raw;
const email = String(body.email || '').trim().toLowerCase();
const optin = Boolean(body.optin);
const site = String(body.site || 'https://palmbeach-vitality.store/');
const source = String(body.source || 'homepage_subscribe_popup');
const shopUrl = String(body.shop_url || (site.replace(/\/?$/, '/') + 'shop/'));
const logoUrl = String(body.logo_url || 'https://palmbeach-vitality.store/wp-content/themes/palmbeach-vitality/assets/images/logo-full.jpg');
const bgUrl = String(body.bg_url || 'https://palmbeach-vitality.store/wp-content/themes/palmbeach-vitality/assets/images/email-intro-bg.jpg');
const couponCode = String(body.coupon_code || '').trim();
const couponPercent = String(body.coupon_percent || '').trim();

if (!email || !email.includes('@')) {
  throw new Error('Missing or invalid email');
}
if (!couponCode) {
  throw new Error('Missing coupon_code from WordPress payload');
}
const percentNum = Number(couponPercent);
if (!Number.isFinite(percentNum) || percentNum <= 0) {
  throw new Error('Missing or invalid coupon_percent from WordPress payload');
}

const subject = 'Welcome to the inner circle — Palm Beach Vitality';
const text = [
  'Welcome to the inner circle.',
  '',
  "You're on the Palm Beach Vitality list — research-driven peptides and performance compounds, built around rigorous quality standards and formulations that actually perform.",
  '',
  "As a subscriber you'll get:",
  '- Weekly / monthly research notes',
  '- ' + couponPercent + '% off your first order with code ' + couponCode,
  '- First access to new compounds',
  '- A direct line to the team',
  '',
  'Explore the catalog: ' + shopUrl,
  '',
  'All products are intended for research purposes only. Not for human consumption.',
  'Questions? Reply to this email or write sales@palmbeach-vitality.com.',
].join('\n');

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head>
<body style="margin:0;padding:0;background:#05080c;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" background="${bgUrl}" style="background-color:#0a0f14;background-image:url(${bgUrl});background-size:cover;background-position:center top;background-repeat:no-repeat;padding:36px 14px;">
    <tr><td align="center">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">
        <tr><td style="height:42px;line-height:42px;font-size:1px;">&nbsp;</td></tr>
        <tr><td style="background:#0c121a;border:1px solid #1e2a38;border-top:3px solid #00d4ff;border-radius:8px;overflow:hidden;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
            <tr><td style="background:#080d14;padding:0;">
              <a href="${shopUrl}" style="display:block;"><img src="${logoUrl}" alt="Palm Beach Vitality" width="600" style="display:block;width:100%;max-width:600px;height:auto;border:0;"></a>
            </td></tr>
            <tr><td style="background:#0a1018;padding:16px 28px;text-align:center;border-bottom:1px solid #1a2430;">
              <div style="font-family:Arial,Helvetica,sans-serif;font-size:13px;letter-spacing:0.28em;color:#00d4ff;font-weight:700;">PALM BEACH VITALITY</div>
              <div style="margin-top:8px;font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:0.18em;color:#9eb6c8;">RESEARCH-DRIVEN PEPTIDES &amp; PERFORMANCE COMPOUNDS</div>
            </td></tr>
            <tr><td style="padding:34px 34px 10px;background:#0c121a;">
              <h1 style="margin:0 0 16px;font-family:Georgia,'Times New Roman',serif;font-size:30px;line-height:1.25;color:#f4f8fb;font-weight:700;">Welcome to the inner circle.</h1>
              <p style="margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#c8d6e0;">You're on the list. We build research-grade peptides around cutting-edge research, rigorous quality standards, and formulations that actually perform — documented, COA-backed, and intended for laboratory use only.</p>
              <p style="margin:0 0 10px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.65;color:#e8f1f7;">As a subscriber you'll get:</p>
              <p style="margin:0 0 6px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.7;color:#c8d6e0;"><span style="color:#00d4ff;">→</span> Weekly / monthly research notes</p>
              <p style="margin:0 0 6px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.7;color:#c8d6e0;"><span style="color:#00d4ff;">→</span> ${couponPercent}% off your first order with code <strong style="color:#00d4ff;font-weight:700;">${couponCode}</strong></p>
              <p style="margin:0 0 6px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.7;color:#c8d6e0;"><span style="color:#00d4ff;">→</span> First access to new compounds</p>
              <p style="margin:0 0 28px;font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.7;color:#c8d6e0;"><span style="color:#00d4ff;">→</span> A direct line to the team</p>
              <table role="presentation" cellpadding="0" cellspacing="0"><tr>
                <td style="background:#00d4ff;border-radius:4px;">
                  <a href="${shopUrl}" style="display:inline-block;padding:14px 26px;font-family:Arial,Helvetica,sans-serif;font-size:13px;letter-spacing:0.1em;text-decoration:none;color:#041018;font-weight:700;">EXPLORE THE CATALOG</a>
                </td>
              </tr></table>
            </td></tr>
            <tr><td style="padding:24px 34px 32px;background:#0c121a;border-top:1px solid #1a2430;">
              <p style="margin:0;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:1.65;color:#7f93a3;">Palm Beach Vitality · Palm Beach County, Florida<br>All products are intended for research purposes only. Not for human consumption. Not evaluated by the FDA.<br>Questions? Reply to this email or write sales@palmbeach-vitality.com.</p>
            </td></tr>
          </table>
        </td></tr>
        <tr><td style="height:42px;line-height:42px;font-size:1px;">&nbsp;</td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;

return [{ json: { email, optin, site, source, shopUrl, logoUrl, bgUrl, couponCode, couponPercent, subject, text, html } }];
